/*
 * [演算法說明]
 * 題目要求在集合 S 中找出最大的 d，使得 a + b + c = d，且 a, b, c, d 為不同元素。
 * 等價於：a + b = d - c。
 * 
 * 演算法步驟：
 * 1. 將集合 S 從大到小排序。
 * 2. 為了最大化 d，我們從最大的元素開始嘗試作為 d。
 * 3. 固定 d 和 c，計算目標值 target = d - c。
 * 4. 在剩餘元素中搜尋是否存在兩個不同的元素 a, b 使得 a + b = target。
 * 5. 由於 a, b, c, d 必須互不相同，需在檢查時排除重複使用。
 * 
 * 時間複雜度：O(N^2)。
 */

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<long long> s(n);
        for (int i = 0; i < n; ++i) cin >> s[i];
        sort(s.rbegin(), s.rend());

        bool found = false;
        for (int i = 0; i < n && !found; ++i) { // d
            for (int j = 0; j < n && !found; ++j) { // c
                if (i == j) continue;
                long long target = s[i] - s[j];
                // Two sum problem: find a + b = target in s
                int left = 0, right = n - 1;
                while (left < right) {
                    if (left == i || left == j) { left++; continue; }
                    if (right == i || right == j) { right--; continue; }

                    long long sum = s[left] + s[right];
                    if (sum == target) {
                        cout << s[i] << endl;
                        found = true;
                        break;
                    } else if (sum > target) {
                        left++;
                    } else {
                        right--;
                    }
                }
            }
        }
        if (!found) cout << "no solution" << endl;
    }
    return 0;
}
